CREATE TABLE public.vessels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.vessels TO authenticated; GRANT ALL ON public.vessels TO service_role;
ALTER TABLE public.vessels ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, username text NOT NULL UNIQUE);
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.vessel_members (user_id uuid PRIMARY KEY, vessel_id uuid NOT NULL REFERENCES public.vessels(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.vessel_members TO authenticated; GRANT ALL ON public.vessel_members TO service_role;
ALTER TABLE public.vessel_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, vessel_id uuid NOT NULL REFERENCES public.vessels(id), role text NOT NULL DEFAULT 'owner', PRIMARY KEY(user_id,vessel_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.vessel_credentials (vessel_id uuid PRIMARY KEY REFERENCES public.vessels(id), password_hash text NOT NULL);
GRANT ALL ON public.vessel_credentials TO service_role;
ALTER TABLE public.vessel_credentials ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.current_vessel() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT vessel_id FROM public.vessel_members WHERE user_id=auth.uid() $$;
CREATE POLICY vessel_read ON public.vessels FOR SELECT TO authenticated USING(id=public.current_vessel());
CREATE POLICY members_read ON public.vessel_members FOR SELECT TO authenticated USING(vessel_id=public.current_vessel());
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR EXISTS(SELECT 1 FROM public.vessel_members m WHERE m.user_id=profiles.id AND m.vessel_id=public.current_vessel()));
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.stock_items ADD COLUMN vessel_id uuid REFERENCES public.vessels(id);
ALTER TABLE public.custom_boxes ADD COLUMN vessel_id uuid REFERENCES public.vessels(id);
ALTER TABLE public.usage_history ADD COLUMN vessel_id uuid REFERENCES public.vessels(id), ADD COLUMN actor_username text;
CREATE TABLE public.tasks (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, vessel_id uuid NOT NULL DEFAULT public.current_vessel() REFERENCES public.vessels(id), text text NOT NULL, notes text, starred boolean NOT NULL DEFAULT false, assignees text[] NOT NULL DEFAULT '{}', completed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, created_by_username text, completed_at timestamptz, completed_by uuid, completed_by_username text);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role;
GRANT USAGE,SELECT ON SEQUENCE public.tasks_id_seq TO authenticated,service_role;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY tasks_access ON public.tasks FOR ALL TO authenticated USING(vessel_id=public.current_vessel()) WITH CHECK(vessel_id=public.current_vessel());
CREATE FUNCTION public.stamp_task_actor() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor text; BEGIN SELECT username INTO actor FROM public.profiles WHERE id=auth.uid(); IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); NEW.created_by_username:=actor; NEW.completed:=false; NEW.completed_at:=null; NEW.completed_by:=null; NEW.completed_by_username:=null; ELSE NEW.created_by:=OLD.created_by; NEW.created_by_username:=OLD.created_by_username; NEW.created_at:=OLD.created_at; NEW.vessel_id:=OLD.vessel_id; IF NEW.completed IS DISTINCT FROM OLD.completed THEN NEW.completed_at:=CASE WHEN NEW.completed THEN now() END; NEW.completed_by:=CASE WHEN NEW.completed THEN auth.uid() END; NEW.completed_by_username:=CASE WHEN NEW.completed THEN actor END; ELSE NEW.completed_at:=OLD.completed_at; NEW.completed_by:=OLD.completed_by; NEW.completed_by_username:=OLD.completed_by_username; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER task_actor BEFORE INSERT OR UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.stamp_task_actor();
CREATE FUNCTION public.assign_inventory_vessel() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN NEW.user_id:=auth.uid(); NEW.vessel_id:=public.current_vessel(); END IF; RETURN NEW; END $$;
CREATE TRIGGER stock_vessel BEFORE INSERT ON public.stock_items FOR EACH ROW EXECUTE FUNCTION public.assign_inventory_vessel();
CREATE TRIGGER box_vessel BEFORE INSERT ON public.custom_boxes FOR EACH ROW EXECUTE FUNCTION public.assign_inventory_vessel();
CREATE FUNCTION public.log_stock_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.quantity IS DISTINCT FROM OLD.quantity AND auth.uid() IS NOT NULL THEN INSERT INTO public.usage_history(item_name,box,quantity,user_id,vessel_id,actor_username) SELECT NEW.name,NEW.box,OLD.quantity-NEW.quantity,auth.uid(),NEW.vessel_id,p.username FROM public.profiles p WHERE p.id=auth.uid(); END IF; RETURN NEW; END $$;
CREATE TRIGGER stock_activity AFTER UPDATE ON public.stock_items FOR EACH ROW EXECUTE FUNCTION public.log_stock_change();
CREATE FUNCTION public.adjust_stock(item_id uuid, delta integer DEFAULT NULL, absolute_quantity integer DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE result integer; BEGIN IF (delta IS NULL)=(absolute_quantity IS NULL) THEN RAISE EXCEPTION 'Choose one quantity adjustment'; END IF; UPDATE public.stock_items SET quantity=greatest(0,CASE WHEN delta IS NOT NULL THEN quantity+delta ELSE absolute_quantity END) WHERE id=item_id RETURNING quantity INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Item unavailable'; END IF; RETURN result; END $$;
GRANT EXECUTE ON FUNCTION public.adjust_stock(uuid,integer,integer) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.adjust_stock(uuid,integer,integer) FROM PUBLIC,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.stock_items,public.custom_boxes TO authenticated; GRANT SELECT ON public.usage_history TO authenticated;
GRANT ALL ON public.stock_items,public.custom_boxes,public.usage_history TO service_role;
CREATE POLICY crew_stock ON public.stock_items FOR ALL TO authenticated USING(vessel_id=public.current_vessel()) WITH CHECK(vessel_id=public.current_vessel());
CREATE POLICY crew_boxes ON public.custom_boxes FOR ALL TO authenticated USING(vessel_id=public.current_vessel()) WITH CHECK(vessel_id=public.current_vessel());
CREATE POLICY crew_history ON public.usage_history FOR SELECT TO authenticated USING(vessel_id=public.current_vessel());
CREATE FUNCTION public.setup_vessel(owner_id uuid, vessel_name text, crew_username text, vessel_password text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE vid uuid; BEGIN IF EXISTS(SELECT 1 FROM public.vessel_members WHERE user_id=owner_id) THEN RAISE EXCEPTION 'Vessel already configured'; END IF; INSERT INTO public.vessels(name) VALUES(vessel_name) RETURNING id INTO vid; INSERT INTO public.profiles(id,username) VALUES(owner_id,crew_username); INSERT INTO public.vessel_members(user_id,vessel_id) VALUES(owner_id,vid); INSERT INTO public.user_roles(user_id,vessel_id) VALUES(owner_id,vid); INSERT INTO public.vessel_credentials VALUES(vid,crypt(vessel_password,gen_salt('bf'))); UPDATE public.stock_items SET vessel_id=vid WHERE user_id=owner_id AND vessel_id IS NULL; UPDATE public.custom_boxes SET vessel_id=vid WHERE user_id=owner_id AND vessel_id IS NULL; UPDATE public.usage_history SET vessel_id=vid WHERE user_id=owner_id AND vessel_id IS NULL; RETURN vid; END $$;
REVOKE ALL ON FUNCTION public.setup_vessel(uuid,text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.setup_vessel(uuid,text,text,text) TO service_role;
CREATE FUNCTION public.verify_vessel_password(vid uuid, candidate text) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$ SELECT password_hash=crypt(candidate,password_hash) FROM public.vessel_credentials WHERE vessel_id=vid $$;
REVOKE ALL ON FUNCTION public.verify_vessel_password(uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.verify_vessel_password(uuid,text) TO service_role;
ALTER PUBLICATION supabase_realtime ADD TABLE public.tasks,public.custom_boxes,public.usage_history;